import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error: {e}')

# Check for sqlite3 import
found_sqlite = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'sqlite3' for name in node.names):
        found_sqlite = True

if not found_sqlite:
    raise AssertionError('Missing import sqlite3')

# Check for INSERT statement
found_insert = False
code_str = user_code.upper()
if 'INSERT INTO PRODUCTS' in code_str and 'WEBCAM' in code_str:
    found_insert = True

if not found_insert:
    raise AssertionError('Task 2: Missing INSERT statement for Webcam')

# Check for SELECT statement
found_select = False
if 'SELECT NAME, PRICE FROM PRODUCTS' in code_str:
    found_select = True

if not found_select:
    raise AssertionError('Task 3: Missing SELECT statement')

# Check for UPDATE statement - more flexible check
found_update = False
update_patterns = [
    'UPDATE PRODUCTS SET PRICE = ? WHERE NAME = ?',
    'UPDATE PRODUCTS SET PRICE=? WHERE NAME=?',
    'UPDATE PRODUCTS SET PRICE = ? WHERE NAME = ?',
    'UPDATE PRODUCTS SET PRICE=? WHERE NAME=?'
]

# Remove all whitespace and compare
code_no_space = ''.join(code_str.split())
for pattern in update_patterns:
    pattern_no_space = ''.join(pattern.split())
    if pattern_no_space in code_no_space:
        found_update = True
        break

if not found_update:
    raise AssertionError('Task 4: Missing UPDATE statement with correct syntax (UPDATE products SET price = ? WHERE name = ?)')

# Check for DELETE statement - more flexible check
found_delete = False
delete_patterns = [
    'DELETE FROM PRODUCTS WHERE NAME = ?',
    'DELETE FROM PRODUCTS WHERE NAME=?',
    'DELETE FROM PRODUCTS WHERE NAME = ?',
    'DELETE FROM PRODUCTS WHERE NAME=?'
]

for pattern in delete_patterns:
    pattern_no_space = ''.join(pattern.split())
    if pattern_no_space in code_no_space:
        found_delete = True
        break

if not found_delete:
    raise AssertionError('Task 6: Missing DELETE statement with correct syntax (DELETE FROM products WHERE name = ?)')

# Check for proper tuple formatting (single value with comma)
found_single_tuple = False
if "('Webcam',)" in user_code or '("Webcam",)' in user_code:
    found_single_tuple = True

if not found_single_tuple:
    raise AssertionError('Tasks 3,5,7: Remember to use a trailing comma for single-value tuples: (\'Webcam\',)')

# Check for commit calls
commit_count = 0
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'commit':
        commit_count += 1

if commit_count < 3:
    raise AssertionError('Tasks 2,4,6: Missing commit() calls after data changes')

print('TEST_PASSED')
